170	### Task Entity
171	```typescript
172	// src/core/domains/task-management/entities/task.entity.ts
173	import { AggregateRoot } from '../../../shared/domain/aggregate-root';
174	import { TaskId } from '../value-objects/task-id.vo';
175	import { TaskStatus } from '../value-objects/task-status.vo';
176	import { Priority } from '../value-objects/priority.vo';
177	import { TaskAssignedEvent } from '../events/task-assigned.event';
178	
179	interface TaskProps {
180	  id: TaskId;
181	  description: string;
182	  priority: Priority;
183	  status: TaskStatus;
184	  assignedAgentId?: string;
185	  createdAt: Date;
186	  updatedAt: Date;
187	}
188	
189	export class Task extends AggregateRoot<TaskId> {
190	  private props: TaskProps;
191	
192	  private constructor(props: TaskProps) {
193	    super(props.id);
194	    this.props = props;
195	  }
196	
197	  static create(description: string, priority: Priority): Task {
198	    const task = new Task({
199	      id: TaskId.create(),
200	      description,
201	      priority,
202	      status: TaskStatus.pending(),
203	      createdAt: new Date(),
204	      updatedAt: new Date()
205	    });
206	
207	    return task;
208	  }
209	
210	  static reconstitute(props: TaskProps): Task {
211	    return new Task(props);
212	  }
213	
214	  public assignTo(agentId: string): void {
215	    if (this.props.status.equals(TaskStatus.completed())) {
216	      throw new Error('Cannot assign completed task');
217	    }
218	
219	    this.props.assignedAgentId = agentId;
220	    this.props.status = TaskStatus.assigned();
221	    this.props.updatedAt = new Date();
222	
223	    this.applyEvent(new TaskAssignedEvent(
224	      this.id.value,
225	      agentId,
226	      this.props.priority
227	    ));
228	  }
229	
230	  public complete(result: TaskResult): void {
231	    if (!this.props.assignedAgentId) {
232	      throw new Error('Cannot complete unassigned task');
233	    }
234	
235	    this.props.status = TaskStatus.completed();
236	    this.props.updatedAt = new Date();
237	
238	    this.applyEvent(new TaskCompletedEvent(
239	      this.id.value,
240	      result,
241	      this.calculateDuration()
242	    ));
243	  }
244	
245	  // Getters
246	  get description(): string { return this.props.description; }
247	  get priority(): Priority { return this.props.priority; }
248	  get status(): TaskStatus { return this.props.status; }
249	  get assignedAgentId(): string | undefined { return this.props.assignedAgentId; }
250	  get createdAt(): Date { return this.props.createdAt; }
251	  get updatedAt(): Date { return this.props.updatedAt; }
252	
253	  private calculateDuration(): number {
254	    return this.props.updatedAt.getTime() - this.props.createdAt.getTime();
255	  }
256	}
