341	@Injectable()
342	export class TaskSchedulingService {
343	  public prioritizeTasks(tasks: Task[]): Task[] {
344	    return tasks.sort((a, b) =>
345	      b.priority.getNumericValue() - a.priority.getNumericValue()
346	    );
347	  }
348	
349	  public canSchedule(task: Task, agentCapacity: number): boolean {
350	    if (agentCapacity <= 0) return false;
351	
352	    // Critical tasks always schedulable
353	    if (task.priority.equals(Priority.critical())) return true;
354	
355	    // Other logic based on capacity
356	    return true;
357	  }
358	
359	  public calculateEstimatedDuration(task: Task): number {
360	    // Simple heuristic - would use ML in real implementation
361	    const baseTime = 300000; // 5 minutes
362	    const priorityMultiplier = {
363	      low: 0.5,
364	      medium: 1.0,
365	      high: 1.5,
366	      critical: 2.0
367	    };
368	
369	    return baseTime * priorityMultiplier[task.priority.value];
370	  }
