389	### SQLite Implementation
390	```typescript
391	// src/core/domains/task-management/repositories/sqlite-task.repository.ts
392	@Injectable()
393	export class SqliteTaskRepository implements ITaskRepository {
394	  constructor(
395	    @Inject('Database') private db: Database,
396	    @Inject('Logger') private logger: ILogger
397	  ) {}
398	
399	  async save(task: Task): Promise<void> {
400	    const sql = `
401	      INSERT OR REPLACE INTO tasks (
402	        id, description, priority, status, assigned_agent_id, created_at, updated_at
403	      ) VALUES (?, ?, ?, ?, ?, ?, ?)
404	    `;
405	
406	    await this.db.run(sql, [
407	      task.id.value,
408	      task.description,
409	      task.priority.value,
410	      task.status.value,
411	      task.assignedAgentId,
412	      task.createdAt.toISOString(),
413	      task.updatedAt.toISOString()
414	    ]);
415	
416	    this.logger.debug(`Task saved: ${task.id.value}`);
417	  }
418	
419	  async findById(id: TaskId): Promise<Task | null> {
420	    const sql = 'SELECT * FROM tasks WHERE id = ?';
421	    const row = await this.db.get(sql, [id.value]);
422	
423	    return row ? this.mapRowToTask(row) : null;
424	  }
425	
426	  async findPendingTasks(): Promise<Task[]> {
427	    const sql = 'SELECT * FROM tasks WHERE status = ? ORDER BY priority DESC, created_at ASC';
428	    const rows = await this.db.all(sql, ['pending']);
429	
430	    return rows.map(row => this.mapRowToTask(row));
431	  }
432	
433	  private mapRowToTask(row: any): Task {
434	    return Task.reconstitute({
435	      id: TaskId.fromString(row.id),
436	      description: row.description,
437	      priority: Priority.fromString(row.priority),
438	      status: TaskStatus.fromString(row.status),
439	      assignedAgentId: row.assigned_agent_id,
440	      createdAt: new Date(row.created_at),
441	      updatedAt: new Date(row.updated_at)
442	    });
443	  }
444	}
