449	### Use Case Implementation
450	```typescript
451	// src/core/application/use-cases/assign-task.use-case.ts
452	@Injectable()
453	export class AssignTaskUseCase {
454	  constructor(
455	    @Inject('TaskRepository') private taskRepository: ITaskRepository,
456	    @Inject('AgentRepository') private agentRepository: IAgentRepository,
457	    @Inject('DomainEventBus') private eventBus: DomainEventBus,
458	    @Inject('Logger') private logger: ILogger
459	  ) {}
460	
461	  async execute(command: AssignTaskCommand): Promise<AssignTaskResult> {
462	    try {
463	      // 1. Validate command
464	      await this.validateCommand(command);
465	
466	      // 2. Load aggregates
467	      const task = await this.taskRepository.findById(command.taskId);
468	      if (!task) {
469	        throw new TaskNotFoundError(command.taskId);
470	      }
471	
472	      const agent = await this.agentRepository.findById(command.agentId);
473	      if (!agent) {
474	        throw new AgentNotFoundError(command.agentId);
475	      }
476	
477	      // 3. Business logic
478	      if (!agent.canAcceptTask(task)) {
479	        throw new AgentCannotAcceptTaskError(command.agentId, command.taskId);
480	      }
481	
482	      task.assignTo(command.agentId);
483	      agent.acceptTask(task.id);
484	
485	      // 4. Persist changes
486	      await Promise.all([
487	        this.taskRepository.save(task),
488	        this.agentRepository.save(agent)
489	      ]);
490	
491	      // 5. Publish domain events
492	      const events = [
493	        ...task.getUncommittedEvents(),
494	        ...agent.getUncommittedEvents()
495	      ];
496	
497	      for (const event of events) {
498	        await this.eventBus.publish(event);
499	      }
500	
501	      task.markEventsAsCommitted();
502	      agent.markEventsAsCommitted();
503	
504	      // 6. Return result
505	      this.logger.info(`Task ${command.taskId.value} assigned to agent ${command.agentId}`);
506	
507	      return AssignTaskResult.success({
508	        taskId: task.id,
509	        agentId: command.agentId,
510	        assignedAt: new Date()
511	      });
512	
513	    } catch (error) {
514	      this.logger.error(`Failed to assign task ${command.taskId.value}:`, error);
515	      return AssignTaskResult.failure(error);
516	    }
517	  }
518	
519	  private async validateCommand(command: AssignTaskCommand): Promise<void> {
520	    if (!command.taskId) {
521	      throw new ValidationError('Task ID is required');
522	    }
523	    if (!command.agentId) {
524	      throw new ValidationError('Agent ID is required');
525	    }
526	  }
527	}
